import {CATEGORIES,LABELS} from './engine.js?v=2.3.0';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const n=v=>Number.isFinite(v)?Number(v.toPrecision(4)).toString():'—';
export function sensitivityTornado(data,mode='steps'){const normalized=mode==='normalized',rows=data.scenarios.filter(s=>s.valid&&Number.isFinite(normalized?s.elasticity:s.lossChange)).map(s=>({...s,value:normalized?s.elasticity:s.lossChange})).sort((a,b)=>Math.abs(b.value)-Math.abs(a.value)),max=Math.max(1e-12,...rows.map(s=>Math.abs(s.value))),height=55+rows.length*35;return `<p class="caption">${normalized?'Normalised local response: loss % per +1% parameter change. °C steps and invalid scenarios are excluded; temperature percentages use Kelvin.':'Actual chosen steps: bars show total loss change %. Different step sizes affect this ranking.'} Model predictions, not circuit re-simulations.</p>${rows.length?`<svg class="chart" viewBox="0 0 840 ${height}" role="img" aria-label="Sensitivity tornado chart"><path d="M540 20V${height-20}" stroke="#8998a6"/>${rows.map((s,j)=>{const width=220*Math.abs(s.value)/max,y=25+j*35;return `<text x="5" y="${y+14}">${e(s.label)} ${s.change>0?'+':''}${n(s.change)} ${e(s.unit)}</text><rect x="${s.value<0?540-width:540}" y="${y}" width="${width}" height="22" fill="${s.value<0?'#79d8c1':'#f49cac'}"><title>${e(s.label)}: ${n(s.value)} ${normalized?'loss % / parameter %':'% total loss'}</title></rect><text x="${s.value<0?535-width:545+width}" y="${y+15}" text-anchor="${s.value<0?'end':'start'}">${n(s.value)}</text>`;}).join('')}</svg>`:'<p>No comparable valid scenarios.</p>'}<p class="caption">${data.scenarios.filter(s=>!s.valid).length} invalid scenarios excluded from bars; errors remain in the table.</p>`;}
export function contributionSensitivity(data){return `<h3>Which loss contribution changes?</h3><div class="table-wrap"><table><thead><tr><th>Parameter / actual step</th>${CATEGORIES.map(k=>`<th>${e(LABELS[k])} ΔW</th>`).join('')}<th>Response interpretation</th></tr></thead><tbody>${data.scenarios.map(s=>`<tr><td>${e(s.label)} ${s.change>0?'+':''}${n(s.change)} ${e(s.unit)}</td>${CATEGORIES.map(k=>`<td>${n(s.categoryDelta?.[k])}</td>`).join('')}<td>${e(s.response||s.errors?.join('; ')||'Not evaluated')}</td></tr>`).join('')}</tbody></table></div><p class="caption">Changes are mean loss in watts over the selected operating points. A zero response with an absent/disabled dependency does not establish physical insensitivity.</p>`;}
